CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'patient', active INTEGER NOT NULL DEFAULT 1, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patients(id INTEGER PRIMARY KEY, user_id INTEGER UNIQUE REFERENCES users(id) ON DELETE SET NULL,
  name TEXT NOT NULL, age INTEGER, gender TEXT, phone TEXT, blood_group TEXT, address TEXT, history TEXT, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS doctors(id INTEGER PRIMARY KEY, user_id INTEGER UNIQUE REFERENCES users(id) ON DELETE SET NULL,
  name TEXT NOT NULL, specialty TEXT NOT NULL, phone TEXT, fee INTEGER DEFAULT 0, available_days TEXT);
CREATE TABLE IF NOT EXISTS appointments(id INTEGER PRIMARY KEY, patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id INTEGER NOT NULL REFERENCES doctors(id) ON DELETE CASCADE, date TEXT NOT NULL, time TEXT NOT NULL, reason TEXT,
  status TEXT NOT NULL DEFAULT 'Pending', created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS beds(id INTEGER PRIMARY KEY, ward TEXT UNIQUE NOT NULL, total INTEGER NOT NULL, occupied INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inventory(id INTEGER PRIMARY KEY, item TEXT NOT NULL, category TEXT, qty INTEGER NOT NULL, unit TEXT, reorder_level INTEGER NOT NULL DEFAULT 10);
CREATE TABLE IF NOT EXISTS feedback(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  rating INTEGER NOT NULL, message TEXT NOT NULL, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS queue_entries(id INTEGER PRIMARY KEY, patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id INTEGER NOT NULL REFERENCES doctors(id) ON DELETE CASCADE, appointment_id INTEGER REFERENCES appointments(id) ON DELETE SET NULL,
  day TEXT NOT NULL, token INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'Waiting', checked_in TEXT NOT NULL, started TEXT, finished TEXT,
  UNIQUE(doctor_id, day, token));
CREATE INDEX IF NOT EXISTS idx_queue_doctor_day ON queue_entries(doctor_id, day, status);
